import { Component, input } from '@angular/core';
import { FigurePipe } from '../../core/locale';
import { StatusSummary } from '../summary/summary';

// The sheet's counters, shown at all times: its people (retired included), its claims per status as the summary
// counts them, and its due-total and overdue-total as the sheet's totals show them;
// and the signed-in user's own due-total and overdue-total, when a person on the sheet has their name; and their crew
// total, the due-totals of the crews that person leads added up, when they lead one; and how many REVIEW claims are
// assigned to them.
@Component({
  selector: 'app-header',
  imports: [FigurePipe],
  template: `
    <header aria-label="Sheet counters">
      <dl>
        <dt>People</dt>
        <dd data-testid="header-people-count">{{ peopleCount() | fig }}</dd>
        @for (s of statuses(); track s.status) {
          <dt>{{ s.status | fig }}</dt>
          <dd [attr.data-testid]="'header-claims-' + s.status + '-count'">{{ s.count | fig }}</dd>
        }
        <dt>Due total</dt>
        <dd data-testid="header-due-total">{{ dueTotal() | fig }}</dd>
        <dt>Overdue total</dt>
        <dd data-testid="header-overdue-total">{{ overdueTotal() | fig }}</dd>
        <dt>My due total</dt>
        <dd data-testid="my-due-total">{{ myDueTotal() | fig }}</dd>
        <dt>My overdue total</dt>
        <dd data-testid="my-overdue-total">{{ myOverdueTotal() | fig }}</dd>
        <dt>My crew total</dt>
        <dd data-testid="my-crew-due-total">{{ myCrewDueTotal() | fig }}</dd>
        <dt>My reviews</dt>
        <dd data-testid="my-reviews-count">{{ myReviewsCount() | fig }}</dd>
      </dl>
    </header>
  `,
})
export class Header {
  readonly peopleCount = input.required<number>();
  readonly statuses = input.required<StatusSummary[]>();
  readonly dueTotal = input.required<string>();
  readonly overdueTotal = input.required<string>();
  readonly myDueTotal = input.required<string>();
  readonly myOverdueTotal = input.required<string>();
  readonly myCrewDueTotal = input.required<string>();
  readonly myReviewsCount = input.required<number>();
}
function csvField(value: string): string {
  return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

// The people on the active sheet, in the order they were added, each with their claims and what
// they have claimed and their due-total, the sheet's claimed-total and due-total, the grades' rates, and the one form that adds a person or, once a
// person's editor is opened, saves that person.
@Component({
  selector: 'app-people',
  imports: [ClassicSummary, Claims, Crews, Header, Periods, PersonPlans, Pools, Rates, Summary, FigurePipe],
  template: `
    <app-header
      [peopleCount]="people().length"
      [statuses]="statusSummary()"
      [dueTotal]="dueTotal()"
      [overdueTotal]="overdueTotal()"
      [myDueTotal]="myDueTotal()"
      [myOverdueTotal]="myOverdueTotal()"
      [myCrewDueTotal]="myCrewDueTotal()"
      [myReviewsCount]="myReviewsCount()"
    />
    <section aria-labelledby="consolidated-heading">
      <h2 id="consolidated-heading">Consolidated (this sheet and its descendants)</h2>
      <dl>
        <dt>People</dt>
        <dd data-testid="consolidated-people-count">{{ consolidatedPeople() | fig }}</dd>
        <dt>Due total</dt>
        <dd data-testid="consolidated-due-total">{{ consolidatedDueTotal() | fig }}</dd>
        <dt>Overdue total</dt>
        <dd data-testid="consolidated-overdue-total">{{ consolidatedOverdueTotal() | fig }}</dd>
        @for (g of consolidatedGrades(); track g.grade) {
      if (!from || person === undefined) continue;
      for (const period of this.periods()) {
        if (from.to >= period.from || !liveAtEnd(c, person, today, period.to)) continue;
        const status = statusOn(c, period.to);
        if (status !== 'OPEN' && status !== 'PENDING') continue;
        const theirs = carried.get(person.id) ?? new Map<string, string[]>();
        const list = theirs.get(period.name) ?? [];
        list.push(claimDue(c, this.rates(), person.grades, this.session));
        theirs.set(period.name, list);
        carried.set(person.id, theirs);
      }
    }
    return new Map(
      [...carried].map(([id, theirs]) => [id, new Map([...theirs].map(([name, list]) => [name, sumDues(list)]))]),
    );
  });
  /** Each period's due-total by name: the sum of everyone's due-total for it. */
  protected readonly periodDueTotals = computed(
    () =>
      new Map(
        this.periods().map((per) => [per.name, sumDues(this.people().map((p) => this.periodDueTotalOf(p, per)))]),
      ),
  );
  /** Everyone's due-total added up, skipping the n/a ones and, with three or more, the highest and lowest. */
  /** Each person's due-total as shown on their row, by person id. */
  protected readonly personDueTotals = computed(() => new Map(this.people().map((p) => [p.id, this.dueTotalOf(p)])));

  protected readonly dueTotal = computed(() => trimmedSumDues(this.people().map((p) => this.dueTotalOf(p))));
  /** Everyone's settled-total added up, not trimmed. */
  protected readonly settledTotal = computed(() => sumDues(this.people().map((p) => this.settledTotalOf(p))));
  /** Everyone's open-total added up, not trimmed. */
  protected readonly openTotal = computed(() => sumDues(this.people().map((p) => this.openTotalOf(p))));
  /** Everyone's age buckets added up, bucket by bucket (0 to 30, 31 to 60, 61 or more days), not trimmed. */
  protected readonly agedTotals = computed<[string, string, string]>(() => {
    const aged = this.people().map((p) => this.agedOf(p));
    return [0, 1, 2].map((i) => sumDues(aged.map((a) => a[i]))) as [string, string, string];
  });
  /** How many of everyone's counted claims are overdue. */
  protected readonly overdueCount = computed(() =>
    this.people().reduce((total, p) => total + this.overdueOf(p).length, 0),
  );
  /** Everyone's overdue-total added up, with three or more leaving out the highest and lowest. */
  protected readonly overdueTotal = computed(() => trimmedSumDues(this.people().map((p) => this.overdueTotalOf(p))));
  /** The person on the sheet with the signed-in user's name, by name or alias as names are compared; none if no one. */
  private readonly me = computed(() => {
    const key = nameKey(this.session.user() ?? '');
    if (!key) return undefined;
    const people = this.people();
    return (
      people.find((p) => nameKey(p.name) === key) ?? people.find((p) => p.aliases.some((a) => nameKey(a) === key))
    );
  });
  /** The signed-in user's own due-total, as their row shows it; blank when no one on the sheet has their name. */
  protected readonly myDueTotal = computed(() => {
    const me = this.me();
    return me ? this.dueTotalOf(me) : '';
  });
  /** The signed-in user's own overdue-total, as their row shows it; blank when no one on the sheet has their name. */
  protected readonly myOverdueTotal = computed(() => {
    const me = this.me();
    return me ? this.overdueTotalOf(me) : '';
  });
  /** Each crew's lead and due-total, as the crews show them. */
  protected readonly crewTotals = signal<CrewTotal[]>([]);
  /** The due-totals of the crews the signed-in user leads, added up; blank when they lead none. */
  protected readonly myCrewDueTotal = computed(() => {
    const me = this.me();
    const led = me ? this.crewTotals().filter((c) => c.leadId === me.id) : [];
    return led.length ? sumDues(led.map((c) => c.dueTotal)) : '';
  });
  /** How many REVIEW claims on the sheet are assigned to the signed-in user. */
  protected readonly myReviewsCount = computed(() => {
    const user = this.session.user() ?? '';
    return this.claims().filter((c) => c.status === 'REVIEW' && c.reviewAssignee === user).length;
  });
  /**
   * The steward's dashboard over the sheet: how many claims are PENDING, how many in REVIEW, and how many that count
   * are overdue; none for a user who is not a steward (as of the as-of date, the role they had then).
   */
  protected readonly dashboard = computed(() => {
    if (!this.session.steward()) return null;
    const claims = this.claims();
    return {
      pending: claims.filter((c) => c.status === 'PENDING').length,
      review: claims.filter((c) => c.status === 'REVIEW').length,
      overdue: this.overdueCount(),
    };
  });
  /** The figures of the sheet's descendants added up, each as that sheet shows them; none until read. */
  private readonly descendantFigures = signal<DescendantFigures>(NO_DESCENDANTS);
  /** Every person of the tree: the sheet's as its rows show them, then its descendants'. */
  private readonly treeMembers = computed<TreeMember[]>(() => [
    ...this.people().map((p) => ({
      dueTotal: this.dueTotalOf(p),
      overdueTotal: this.overdueTotalOf(p),
      names: [p.name, ...p.aliases].map(nameKey),
    })),
    ...this.descendantFigures().members,
  ]);
  /** The people of the tree, each counted once: people whose names or aliases match are one. */
  protected readonly consolidatedPeople = computed(() => distinctPeople(this.treeMembers()));
